window.docContents[9].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/Irreducible-representations-of-Z___pZ-in-characteristic-p-are-trivial/#Chapter4___Example4___1___3":{"contents":"Example 4.1.3. If G = \\mathbb{Z}/p\\mathbb{Z} and k has characteristic p, then every irreducible representation of G over k is trivial (so k[\\mathbb{Z}/p\\mathbb{Z}] indeed is not semisimple). Indeed, an irreducible representation of this group is a 1-dimensional space on which the generator acts by a pth root of unity. But every pth root of unity in k equals 1, as x^p - 1 = (x - 1)^p over k.\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results\t4.1. Maschke's theorem\tIrreducible representations of Z/pZ in characteristic p are trivial","header":"Irreducible representations of Z/pZ in characteristic p are trivial","id":"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/Irreducible-representations-of-Z___pZ-in-characteristic-p-are-trivial/#Chapter4___Example4___1___3"}});
